<?php require_once 'config.php';$ready=table_exists($conn,'product_reviews');$reviews=[];$summary=['n'=>0,'avg'=>0];if($ready){$reviews=$conn->query("SELECT r.rating,r.review_text,r.admin_reply,r.created_at,u.name AS user_name,p.id AS product_id,p.name AS product_name,p.image,p.product_type FROM product_reviews r JOIN users u ON u.id=r.user_id JOIN products p ON p.id=r.product_id WHERE r.status='approved' AND p.is_active=1 ORDER BY r.created_at DESC LIMIT 60")->fetch_all(MYSQLI_ASSOC);$summary=$conn->query("SELECT COUNT(*) n, COALESCE(AVG(rating),0) avg FROM product_reviews WHERE status='approved'")->fetch_assoc();}?>
<!doctype html><html lang="uk"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Відгуки — flora.atelier</title><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/flor-v5.css"><link rel="stylesheet" href="css/flor-v6.css"><link rel="stylesheet" href="css/flor-v7.css"><link rel="stylesheet" href="css/flor-v8.css"><link rel="stylesheet" href="css/flor-v9.css"></head><body><?php require 'header.php';?><main class="page-shell"><div class="page-intro"><span class="eyebrow">ЩИРІ СЛОВА</span><h1>Любов, якою <em>діляться</em></h1><p>Враження покупців від наших квітів та композицій.</p><div class="intro-rating"><span class="stars">★★★★★</span> <?=number_format((float)$summary['avg'],1)?> · <?= (int)$summary['n']?> відгуків</div></div><div class="review-gallery"><?php if(!$ready):?><div class="empty-state">Для запуску відгуків імпортуйте upgrade_v3.sql.</div><?php elseif(!$reviews):?><div class="empty-state">Перші відгуки скоро з'являться тут. ♡</div><?php else:foreach($reviews as $r):?><article class="testimonial"><div class="testimonial-inner"><span class="stars"><?=str_repeat('★',(int)$r['rating'])?></span><p>“<?=e($r['review_text'])?>”</p><strong><?=e($r['user_name'])?></strong><small><?=date('d.m.Y',strtotime($r['created_at']))?></small><?php if($r['admin_reply']):?><div class="admin-reply"><b>✳ flora.atelier</b><p><?=e($r['admin_reply'])?></p></div><?php endif;?></div><a href="view_page.php?pid=<?=(int)$r['product_id']?>" class="testimonial-product"><img src="<?=e(photo($r['image'], $r['product_type'] ?? ''))?>" loading="lazy" alt="" onerror="this.onerror=null;this.src='assets/flower-placeholder.svg'"><span><?=e($r['product_name'])?> ↗</span></a></article><?php endforeach;endif;?></div></main><?php require 'footer.php';?></body></html>
